PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE,role TEXT NOT NULL,active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,registration TEXT NOT NULL UNIQUE,profile TEXT NOT NULL,unit TEXT DEFAULT 'Matriz',active INTEGER NOT NULL DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS certifications(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER NOT NULL,type TEXT NOT NULL,code TEXT,issuer TEXT,issued_at TEXT,expires_at TEXT,status TEXT NOT NULL DEFAULT 'VALIDA',FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS availabilities(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,kind TEXT NOT NULL,FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS shifts(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,unit TEXT DEFAULT 'Matriz',start_time TEXT NOT NULL,end_time TEXT NOT NULL,required_count INTEGER DEFAULT 1,required_certification TEXT,status TEXT DEFAULT 'ATIVO');
CREATE TABLE IF NOT EXISTS schedules(id INTEGER PRIMARY KEY AUTOINCREMENT,shift_id INTEGER,schedule_date TEXT,status TEXT DEFAULT 'RASCUNHO',FOREIGN KEY(shift_id) REFERENCES shifts(id));
CREATE TABLE IF NOT EXISTS allocations(id INTEGER PRIMARY KEY AUTOINCREMENT,schedule_id INTEGER,employee_id INTEGER,status TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(schedule_id) REFERENCES schedules(id),FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS journeys(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER,allocation_id INTEGER,start_at TEXT,end_at TEXT,status TEXT,FOREIGN KEY(employee_id) REFERENCES employees(id));
CREATE TABLE IF NOT EXISTS conflicts(id INTEGER PRIMARY KEY AUTOINCREMENT,employee_id INTEGER,type TEXT,severity TEXT DEFAULT 'ALTA',description TEXT,status TEXT DEFAULT 'ABERTO',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY AUTOINCREMENT,plate TEXT UNIQUE,description TEXT,status TEXT DEFAULT 'DISPONIVEL');
CREATE TABLE IF NOT EXISTS domain_events(id INTEGER PRIMARY KEY AUTOINCREMENT,event_type TEXT,status TEXT,payload TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO settings(key,value) VALUES('REST_MIN_HOURS','11'),('CERTIFICATE_ALERT_DAYS','30');
